      or base_tuple[i] raised to exponent[i] (if exponent is a tuple)

    Raises:
    - TypeError if input types are not as expected
    - ValueError if tuple lengths don't match when exponent is a tuple
    """
    # Validate base_tuple
    if not isinstance(base_tuple, tuple):
        raise TypeError("base_tuple must be a tuple")
    if not all(isinstance(x, (int, float)) for x in base_tuple):
        raise TypeError("All elements of base_tuple must be int or float")

    # Check exponent type
    if isinstance(exponent, (int, float)):
        # Uniform exponent to all elements
        return tuple(pow(x, exponent) for x in base_tuple)

    elif isinstance(exponent, tuple):
        if len(exponent) != len(base_tuple):
