def find_solution(a, b, n):
    """
    Find integers x and y such that a*x + b*y = n, if possible.
    Uses the Extended Euclidean Algorithm.

    Returns:
        (x, y) tuple if a solution exists, otherwise None.
    """

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x1, y1 = extended_gcd(b, a % b)
            x = y1
            y = x1 - (a // b) * y1
            return (g, x, y)

