def next_smallest_palindrome(num: int) -> int:
    """
    Given an integer num, return the smallest palindrome strictly greater than num.
    """
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    s = str(num + 1)  # start searching from the next number

    # If all digits are 9, the next palindrome is 10...01 (e.g. 9 -> 11, 99 -> 101)
    if is_all_nines(s):
        return int('1' + ('0' * (len(s)-1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    length = len(s)
    half_len = (length + 1) // 2  # length of the left half (including middle if odd)
    left = s[:half_len]

    # Construct palindrome by mirroring left to right
    palindrome = make_palindrome(left, length % 2 != 0)

    if palindrome > s:
        return int(palindrome)
    else:
        # If palindrome is not greater than s, increment the left half and mirror again
        # Increment left half as a number
        left_num = int(left) + 1
        left = str(left_num)

        # If incrementing left caused length change (e.g. 999 + 1 = 1000)
        # then palindrome length increases by 1 or 2 digits
        if len(left) > half_len:
            # For example: 999 -> 1000
            # The next palindrome will be 10001 for odd length or 100001 for even length
            # So just return 10...01 with length+1 digits
            return int('1' + ('0' * (length - 1)) + '1')

        palindrome = make_palindrome(left, length % 2 != 0)
        return int(palindrome)


