def drop_empty(mapping):
    """
    Return a new dictionary with entries removed where the value is considered blank.
    Here, blank entries are defined as:
      - None
      - Empty strings (including strings with only whitespace)

    Other falsey values like 0, False, empty containers (list, dict, etc.) are retained.
    """
    def is_blank(value):
        if value is None:
            return True
        if isinstance(value, str) and value.strip() == '':
            return True
        return False

    return {k: v for k, v in mapping.items() if not is_blank(v)}


