def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students based on height and width criteria.

    Parameters:
        data (dict): Dictionary where keys are student names and values are dictionaries with 'height' and 'width'.
                     Example: {'Alice': {'height': 160, 'width': 50}, 'Bob': {'height': 170, 'width': 55}}
        min_height (int or float, optional): Minimum height to filter.
        max_height (int or float, optional): Maximum height to filter.
        min_width (int or float, optional): Minimum width to filter.
        max_width (int or float, optional): Maximum width to filter.

    Returns:
        dict: Filtered dictionary of students meeting the criteria.
    """
    filtered = {}
    for student, measurements in data.items():
        height = measurements.get('height')
        width = measurements.get('width')

        if height is None or width is None:
            # Skip if height or width is missing
            continue

        if min_height is not None and height < min_height:
            continue
        if max_height is not None and height > max_height:
            continue
        if min_width is not None and width < min_width:
            continue
        if max_width is not None and width > max_width:
            continue

        filtered[student] = measurements

    return filtered


